/* Framegami browser application. Shared pure functions are prepended at build time. */
(function () {
'use strict';
const DATA=window.IRO_DATA, CONFIG=window.IRO_CONFIG;
if(!DATA||!CONFIG) throw new Error('Framegami data is missing. Rebuild the project.');
const styles=DATA.styles,categories=DATA.categories,sources=DATA.sources;
const byId=new Map(styles.map(s=>[s.id,s])), catMap=new Map(categories.map(c=>[c.id,c]));
const known=new Set(byId.keys()), index=buildSearchIndex(styles,categories);
const STORAGE='iro-v1';
let storageWarning=false;
const sessionStore=new Map();
function readLocal(key,fallback){try{const v=localStorage.getItem(STORAGE+':'+key);return v?JSON.parse(v):(sessionStore.has(key)?sessionStore.get(key):fallback);}catch{storageWarning=true;return sessionStore.has(key)?sessionStore.get(key):fallback;}}
function writeLocal(key,value){sessionStore.set(key,value);try{localStorage.setItem(STORAGE+':'+key,JSON.stringify(value));return true;}catch{storageWarning=true;return false;}}
const importedSaved=(()=>{try{return validateImport({schema:'iro-backup/v1',favorites:readLocal('favorites',[]),custom:readLocal('custom',[])},known);}catch{return {favorites:[],custom:[]};}})();
const rootURL=new URL(CONFIG.base||'./',location.href);
const state={lang:CONFIG.lang||'zh',page:CONFIG.page||'atlas',id:CONFIG.id||'',...readQuery(location.search),favorites:new Set(importedSaved.favorites),custom:importedSaved.custom,
 compare:normalizeCompare(readLocal('compare',[]),known),view:readLocal('view','grid')==='compact'?'compact':'grid',limit:24,model:'chatgpt',promptLang:CONFIG.lang||'zh',
 workStyle:styles[0].id,workModel:'chatgpt',workLang:CONFIG.lang||'zh',workOptions:{background:'keep',palette:'style',detail:'balanced',extra:''},workText:'',workDirty:false,customEditing:null};
let localImageURL='', toastTimer, scrollMemory=0, searchTimer, importPayload=null;
const t=(zh,en)=>state.lang==='zh'?zh:en;
const e=escapeHTML;
function icon(name){const paths={search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4.5 4.5"/>',arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>',external:'<path d="M14 3h7v7M21 3l-10 10M11 5H4v15h15v-7"/>',heart:'<path d="M20.8 5.7a5.5 5.5 0 0 0-8 0l-.8.8-.8-.8a5.5 5.5 0 0 0-8 7.5L12 22l8.8-8.8a5.5 5.5 0 0 0 0-7.5Z"/>',compare:'<path d="M3 4h7v16H3zM14 4h7v16h-7z"/>',grid:'<path d="M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z"/>',list:'<path d="M4 5h3v3H4zM11 6h10M4 11h3v3H4zM11 12h10M4 17h3v3H4zM11 18h10"/>',copy:'<rect x="8" y="8" width="12" height="13" rx="1"/><path d="M16 8V3H3v13h5"/>',edit:'<path d="m4 16 12-12 4 4-12 12H4v-4ZM14 6l4 4"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 10v7M12 6v1"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',close:'<path d="m5 5 14 14M19 5 5 19"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 15v6h16v-6"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 16v5h16v-5"/>',book:'<path d="M3 4h8l1 2 1-2h8v16h-8l-1 1-1-1H3zM12 6v15"/>',plus:'<path d="M12 4v16M4 12h16"/>',check:'<path d="m4 12 5 5L20 6"/>',back:'<path d="M20 12H5m6-6-6 6 6 6"/>',github:'<path d="M9 20c-5 1.5-5-2.5-7-3m14 6v-3.9a3.4 3.4 0 0 0-.9-2.7c3-.3 6.2-1.5 6.2-6.9A5.4 5.4 0 0 0 19.8 6a5 5 0 0 0-.1-3.5s-1.2-.4-3.8 1.4a13.3 13.3 0 0 0-7 0C6.3 2.1 5.1 2.5 5.1 2.5A5 5 0 0 0 5 6a5.4 5.4 0 0 0-1.5 3.8c0 5.4 3.2 6.6 6.2 6.9A3.4 3.4 0 0 0 8.8 19V23"/>'};return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.book}</svg>`;}
function l(obj){return obj[state.lang];}
function catName(id){const c=catMap.get(id);return c?c[state.lang]:id;}
function familyName(s){return catMap.get(s.category)?.families[s.family]?.[state.lang==='zh'?0:1]||s.family;}
function counts(id){return styles.filter(s=>s.category===id).length;}
function ex(s,model=null,lang=null){return getDisplaySample(s,model,lang);}
function asset(path){return DATA.embeddedAssets?.[path]||new URL(path,rootURL).href;}
function getPath(page=state.page,id=state.id,lang=state.lang){return lang+'/'+(page==='atlas'?'':page==='style'?'style/'+id+'/':page+'/');}
function params(){const p=new URLSearchParams();for(const key of ['q','category','family','tag','status','sort','treatment']) if(state[key] && !(['all','editorial'].includes(state[key])))p.set(key,state[key]);return p.toString();}
function viewParams(page){if(page==='atlas'||page==='favorites')return params();if(page==='compare'){const p=new URLSearchParams();if(state.compare.length)p.set('ids',state.compare.join(','));p.set('model',state.model);p.set('pl',state.promptLang);return p.toString();}return '';}
function href(page,id='',lang=state.lang){const q=viewParams(page),route=getPath(page,id,lang)+(q?'?'+q:'');if(CONFIG.preview)return '#'+route;return new URL(route,rootURL).href;}
function syncURL(replace=false){const url=href(state.page,state.id);if(CONFIG.preview)history[replace?'replaceState':'pushState']({iro:true},'',url);else if(location.protocol!=='file:')history[replace?'replaceState':'pushState']({iro:true},'',url);}
function parseRoute(){if(CONFIG.preview){if(!location.hash)return;const [route,query='']=location.hash.slice(1).split('?');const parts=route.split('/').filter(Boolean);state.lang=LANGS.includes(parts[0])?parts.shift():state.lang;state.page=parts[0]||'atlas';state.id=parts[0]==='style'?parts[1]||'':'';Object.assign(state,readQuery('?'+query));}else if(location.protocol!=='file:'){let relative=location.pathname.slice(rootURL.pathname.length);const parts=relative.split('/').filter(Boolean);state.lang=LANGS.includes(parts[0])?parts.shift():state.lang;state.page=parts[0]||'atlas';state.id=state.page==='style'?parts[1]||'':'';Object.assign(state,readQuery(location.search));}}
function restoreViewQuery(){const raw=CONFIG.preview?(location.hash.split('?')[1]||''):location.search;const q=readComparisonQuery(raw,known);if(state.page==='compare'&&q.ids!==null)state.compare=q.ids;if(q.model)state.model=q.model;if(q.lang)state.promptLang=q.lang;}
parseRoute();restoreViewQuery();
function toast(message){if(storageWarning&&/已收藏到当前浏览器|已保存到当前浏览器|当前配方已保存|Saved on this browser|Custom recipe saved in this browser|Recipe saved\./.test(message))message=t('已暂存当前会话；浏览器无法持久保存，请导出备份。','Kept for this session only. Browser persistence is unavailable; export a backup.');clearTimeout(toastTimer);const el=document.getElementById('toast');if(!el)return;el.textContent=message;el.classList.add('show');toastTimer=setTimeout(()=>el.classList.remove('show'),2800);}
function persist(){const writes=[writeLocal('favorites',[...state.favorites]),writeLocal('custom',state.custom),writeLocal('compare',state.compare)];const ok=writes.every(Boolean);if(!ok)toast(t('浏览器存储不可用，请导出备份。','Browser storage unavailable. Export a backup.'));return ok;}
function navigate(page='atlas',id='',opts={}){if(state.page==='atlas')scrollMemory=window.scrollY;state.page=page;state.id=id;if(opts.resetLimit)state.limit=24;syncURL();renderShell();renderPage();window.scrollTo({top:opts.restore?scrollMemory:0,behavior:'instant'});document.getElementById('main')?.focus({preventScroll:true});}
function footer(){return `<footer class="site-footer"><div><a href="${href('atlas')}" data-nav="atlas">Framegami · ${t('图生图风格图鉴','Style Atlas')}</a> &nbsp; / &nbsp; EDITION 00 — 2026</div><div class="footer-note">${t('独立风格研究 · 本地收藏 · 不收集 API Key · 不在线生图','Independent style research · Local collections · No API keys · No online generation')}</div><a href="${href('about')}" data-nav="about">${t('来源与验证标准','Sources & validation')} ↗</a></footer>`;}
function sidebarContent(){return `<span class="sidebar-label">${t('我的阅览室','READING ROOM')}</span><a class="side-link ${state.page==='atlas'&&!state.category?'active':''}" href="${href('atlas')}" data-nav="atlas" data-clear="true">${icon('grid')}${t('全部风格研究','All style recipes')}<span class="side-count">${styles.length}</span></a><a class="side-link ${state.page==='favorites'?'active':''}" href="${href('favorites')}" data-nav="favorites">${icon('heart')}${t('我的收藏','My collection')}<span class="side-count" data-fav-count>${state.favorites.size}</span></a><a class="side-link ${state.page==='custom'?'active':''}" href="${href('custom')}" data-nav="custom">${icon('edit')}${t('自定义配方','Custom recipes')}<span class="side-count" data-custom-count>${state.custom.length}</span></a><a class="side-link ${state.page==='workbench'?'active':''}" href="${href('workbench')}" data-nav="workbench">${icon('book')}${t('提示词工作台','Prompt workbench')}</a><div class="side-divider"></div><span class="sidebar-label">${t('按风格门类探索','EXPLORE BY MEDIUM')}</span>${categories.map(c=>`<button class="cat-button ${state.category===c.id&&state.page==='atlas'?'active':''}" data-category="${c.id}" ${state.category===c.id?'aria-expanded="true"':'aria-expanded="false"'}><span class="cat-glyph">${c.glyph}</span>${e(c[state.lang])}<span class="side-count">${counts(c.id)}</span></button>${state.category===c.id?`<div class="family-children">${Object.entries(c.families).map(([id,labels])=>`<button class="${state.family===id?'active':''}" data-family="${id}" data-parent="${c.id}">${e(labels[state.lang==='zh'?0:1])} <span class="side-count">${styles.filter(s=>s.category===c.id&&s.family===id).length}</span></button>`).join('')}</div>`:''}`).join('')}<div class="side-divider"></div><div class="side-note"><strong>${t('研究预览，不是已验证图库','Research preview, not a tested gallery')}</strong><br>${styles.filter(s=>ex(s)).length? t('包含独立案例、拼图临时预览和 B00 程序化风格示意，均明确标注。','Independent showcases, montage crops and B00 procedural studies are separately labeled.') : t('封面是抽象索引图形，不是 AI 转绘例图。','Covers are abstract index graphics, not AI restyling examples.')}</div><a class="side-link" href="${href('about')}" data-nav="about">${icon('info')}${t('方法、来源与贡献','Method, sources & contribution')}</a>`;}
function renderShell(){document.documentElement.lang=state.lang==='zh'?'zh-CN':'en';const current=state.page;document.getElementById('site-head').innerHTML=`<a class="brand" href="${href('atlas')}" data-nav="atlas" aria-label="Framegami ${t('首页','Home')}"><span class="wordmark">Framegami</span><span class="seal">图鉴</span><span class="brand-sub">IMAGE TO IMAGE<br>STYLE ATLAS</span></a><nav class="top-nav" aria-label="${t('主导航','Main navigation')}">${[['atlas','风格图鉴','Atlas'],['workbench','提示词工作台','Workbench'],['favorites','我的收藏','Collection'],['about','关于','About']].map(([page,zh,en])=>`<a href="${href(page)}" data-nav="${page}" ${current===page?'aria-current="page"':''}>${t(zh,en)}</a>`).join('')}</nav><div class="header-tools"><span class="edition hide-tablet"><span class="status-dot"></span>RESEARCH PREVIEW</span><button class="language-button" data-action="language" aria-label="${t('切换到英文','Switch to Chinese')}">${state.lang==='zh'?'中 / EN':'EN / 中'}</button><a class="icon-button header-github" href="https://github.com/patshin/framegami" aria-label="${t('GitHub 源码','GitHub repository')}">${icon('github')}</a><button class="icon-button mobile-menu-btn" data-action="menu" aria-label="${t('打开导航','Open navigation')}">${icon('menu')}</button></div>`;
 document.getElementById('sidebar').innerHTML=sidebarContent();document.getElementById('mobile-menu').innerHTML=`<div class="dialog-head"><h2>${t('Framegami｜图生图风格图鉴','Framegami · Style Atlas')}</h2><button data-close aria-label="${t('关闭导航','Close navigation')}">${icon('close')}</button></div>${sidebarContent()}`;document.getElementById('skip-link').textContent=t('跳到内容','Skip to content');renderTray();}
const palettePairs=[['#cfc3a7','#425f61','#ba7250'],['#d5c2b1','#9d5149','#546d68'],['#d9d5c4','#546b4b','#ae8c50'],['#c4cbd0','#405a73','#ba7a56'],['#d8c2be','#986c76','#385e65'],['#d2cbbb','#746657','#be7448']];
function abstractArt(s,large=false){const p=palettePairs[(s.order-1)%palettePairs.length];return `<div class="abstract kind-${(s.order-1)%6}" style="--bg:${p[0]};--tone:${p[1]};--tone2:${p[2]}"><i></i><span class="cover-monogram" aria-hidden="true">${e(state.lang==='zh'?s.name.zh.slice(0,2):s.name.en.split(/[ -]/).slice(0,2).map(x=>x[0]).join(''))}</span></div><span class="cover-id">Framegami — ${String(s.order).padStart(3,'0')}</span><span class="cover-label">${t('索引封面 · 非生成例图','INDEX COVER · NOT AN AI EXAMPLE')}</span>`;}
function cover(s,large=false,model=null,lang=null){const example=ex(s,model,lang);return example?`<img src="${asset(!large && !CONFIG.preview && example.thumbnailPath ? example.thumbnailPath : example.path)}" alt="${e(l(s.name))} — ${e(example.model||'showcase')}" loading="lazy" decoding="async" width="800" height="800"><span class="cover-label">${example.accepted?t('对应生成例图','GENERATED EXAMPLE'):example.kind==='montage-derived-preview'?t('拼图截取 · 临时参考','MONTAGE CROP · PROVISIONAL'):example.kind==='procedural-style-study'?t('程序化预览 · 非模型生图','PROCEDURAL · NOT AI-GENERATED'):example.requestKind==='standalone-same-scene-generation'?t('独立生成 · 同场景示意','INDEPENDENT · SAME-SCENE REFERENCE'):t('同图案例图','SAME-INPUT SHOWCASE')}</span>`:abstractArt(s,large);}
function card(s){return `<article class="style-card" data-card="${s.id}"><a class="card-link" href="${href('style',s.id)}" data-nav="style" data-id="${s.id}" aria-label="${e(l(s.name))} — ${t('查看提示词','View recipe')}"><div class="card-cover">${cover(s)}</div><div class="card-meta"><h3 class="card-title">${e(l(s.name))}</h3><p class="card-en">${e(state.lang==='zh'?s.name.en:familyName(s))}</p><div class="card-bottom"><span>${e(familyName(s))}</span><span class="status-tag ${ex(s)?.kind==='same-input-showcase'||ex(s)?.accepted?'good':''}">${ex(s)?.kind==='montage-derived-preview'?t('拼图临时示意','Montage preview'):ex(s)?.kind==='procedural-style-study'?t('算法预览','Procedural preview'):ex(s)?t('有例图','Example'):t('待实测','Untested')}</span></div></div></a><div class="card-tools"><button class="favorite-btn" data-favorite="${s.id}" aria-pressed="${state.favorites.has(s.id)}" aria-label="${t('收藏','Save')} ${e(l(s.name))}">${icon('heart')}</button><button class="compare-btn" data-compare="${s.id}" aria-pressed="${state.compare.includes(s.id)}" aria-label="${t('加入比较','Compare')} ${e(l(s.name))}">${icon('compare')}</button></div></article>`;}
function hero(){return `<section class="hero" aria-labelledby="hero-title"><div><div class="eyebrow">A FIELD GUIDE TO VISUAL POSSIBILITIES</div><h1 id="hero-title">${t('同一张图，<br>遇见<em>另一种表达。</em>','One image.<br><em>Another way to see.</em>')}</h1><p class="hero-description">${t('从一根铅笔线，到一层矿物色。探索细分的视觉语言，找到你的画风，把它带进自己的创作。','From a pencil line to a layer of mineral color. Explore distinct visual languages, find your treatment, and bring it into your own practice.')}</p><div class="hero-actions"><a class="button primary" href="#explore" data-action="explore">${t('翻开风格图鉴','Explore the atlas')}${icon('arrow')}</a><a class="button ghost" href="${href('workbench')}" data-nav="workbench">${t('写下自己的配方','Make a recipe')}</a></div><div class="hero-stats"><div class="stat"><strong>${styles.length}</strong><span>${t('风格配方草案','Authored recipe drafts')}</span></div><div class="stat"><strong>${categories.length}</strong><span>${t('视觉门类','Visual categories')}</span></div><div class="stat"><strong>${styles.filter(s=>ex(s)).length}</strong><span>${t('有视觉示意的风格','Styles with visual previews')}</span></div></div></div><div class="specimen-stage" aria-hidden="true"><div class="specimen first" data-caption="FORM / かたち"><div class="abstract kind-2" style="--bg:#526b70;--tone:#d8c7a5;--tone2:#aa6249"><i></i></div></div><div class="specimen second" data-caption="COLOUR / いろ"><div class="abstract kind-1" style="--bg:#cfaa8d;--tone:#bd7556;--tone2:#364f52"><i></i></div></div><div class="specimen third" data-caption="TEXTURE / てざわり"><div class="abstract kind-0" style="--bg:#d1c3a7;--tone:#596c51;--tone2:#be7a4d"><i></i></div></div><div class="stage-foot">${t('视觉索引设计 / 非 AI 转绘样片','INDEX ARTWORK / NOT GENERATED STYLE SAMPLES')}</div></div></section>`;}
function notice(){const shown=styles.filter(s=>ex(s)).length,montage=styles.filter(s=>ex(s)?.kind==='montage-derived-preview').length,procedural=styles.filter(s=>ex(s)?.kind==='procedural-style-study').length;return `<div class="research-notice">${icon('info')}<div><strong>${t('研究预览版','Research preview')}</strong> &nbsp; ${t(`目前 ${shown}/${styles.length} 种风格有视觉示意：${montage} 张拼图裁切、${procedural} 张 B00 程序化预览，均不计为独立 AI 生成；严格逐字 Prompt 验证仍为 0。`,`Visual coverage ${shown}/${styles.length}: ${montage} montage crops and ${procedural} B00 procedural studies. Neither counts as an independent AI-generated result; exact-prompt validation remains zero.`)}</div><a class="notice-link" href="${href('about')}" data-nav="about">${t('查看来源记录','View provenance')} ↗</a></div>`;}
function filteredEntries(){return searchStyles(index,{...state,lang:state.lang,favorites:state.page==='favorites'?state.favorites:null});}
function filtersMarkup(){const tags=[['','全部','All'],['japan','日系细分','Japanese'],['china','中国绘画','Chinese'],['linework','线条与印刷','Line & print'],['tactile','手工质感','Tactile'],['illustrated','动画与插画','Illustrated'],['retro','复古媒介','Retro'],['lab','创意改造','Lab']];return `<div class="treatment-row" role="group" aria-label="${t('转换类型','Treatment type')}">${[['all','全部条目','All entries'],['restyle','主馆 · 保留原图','Atlas · Preserve composition'],['lab','实验室 · 创意重构','Lab · Creative reinterpretation']].map(([id,zh,en])=>`<button data-treatment="${id}" class="${state.treatment===id?'active':''}" aria-pressed="${state.treatment===id}">${t(zh,en)} <small>${id==='all'?styles.length:styles.filter(s=>(s.preservation==='reinterpret')===(id==='lab')).length}</small></button>`).join('')}</div><div class="search-row"><label class="search-box">${icon('search')}<span class="sr-only">${t('搜索风格、技法和别名','Search styles, techniques and aliases')}</span><input id="style-search" type="search" maxlength="300" value="${e(state.q)}" placeholder="${t('搜索画风、技法或关键词，例如：水彩 / Pixar / shin-hanga','Search a style or technique: watercolor, Pixar, shin-hanga…')}" autocomplete="off"><kbd class="keyboard-hint">/</kbd></label><select id="status-filter" class="small-select" aria-label="${t('验证状态','Validation status')}"><option value="all">${t('所有研究条目','All research entries')}</option><option value="images">${t('仅有案例图','With showcase images')}</option><option value="missing-images">${t('尚无案例图','Without showcase images')}</option><option value="examples">${t('仅有严格验证例图','With validated examples only')}</option></select><select id="sort-filter" class="small-select" aria-label="${t('排序方式','Sort order')}"><option value="editorial">${t('编辑顺序','Editorial order')}</option><option value="name">${t('按名称排序','Name')}</option><option value="category">${t('按门类排序','Category')}</option></select><div class="display-buttons" role="group" aria-label="${t('显示方式','Display mode')}"><button data-view="grid" class="${state.view==='grid'?'active':''}" aria-pressed="${state.view==='grid'}" aria-label="${t('网格视图','Grid view')}">${icon('grid')}</button><button data-view="compact" class="${state.view==='compact'?'active':''}" aria-pressed="${state.view==='compact'}" aria-label="${t('紧凑视图','Compact view')}">${icon('list')}</button></div></div><div class="filter-row">${tags.map(([tag,zh,en])=>`<button class="filter-chip ${state.tag===tag?'active':''}" data-tag="${tag}" aria-pressed="${state.tag===tag}">${t(zh,en)}</button>`).join('')}${state.category||state.family?`<button class="filter-chip clear" data-action="clear-filters">${t('清除分类','Clear category')} ×</button>`:''}</div>${state.category?`<div class="catalog-rail" aria-label="${t('细分风格家族','Style families')}"><button data-family="" data-parent="${state.category}" class="${!state.family?'active':''}">${t('全部家族','All families')}</button>${Object.entries(catMap.get(state.category)?.families||{}).map(([id,n])=>`<button data-family="${id}" data-parent="${state.category}" class="${state.family===id?'active':''}">${e(n[state.lang==='zh'?0:1])}</button>`).join('')}</div>`:''}`;}
function renderAtlas(favorites=false){const main=document.getElementById('main');main.innerHTML=`${favorites?`<section class="page-heading"><div class="eyebrow">YOUR PERSONAL READING ROOM</div><h1>${t('把喜欢的，留在这里。','Keep what speaks to you.')}</h1><p>${t('收藏仅保存在当前浏览器。导出备份后可在其他设备导入，不需要账户。','Collections live in this browser. Export and import a backup to move them between devices—no account required.')}</p><div class="action-row"><button class="button small" data-action="export">${icon('download')}${t('导出备份','Export backup')}</button><button class="button small" data-action="import">${icon('upload')}${t('导入备份','Import backup')}</button></div></section>`:hero()+notice()}<section id="explore"><div class="explore-head"><div><h2 class="section-title">${favorites?t('我的风格收藏','My collection'):state.category?e(catName(state.category)):t('风格研究目录','The research atlas')}</h2><span class="section-sub">${favorites?'SAVED FOR LATER':'EXPLORE / FIND / MAKE IT YOURS'}</span></div><span class="edition"><span class="status-dot"></span>${t('提示词双语 · 例图待测','BILINGUAL RECIPES · UNTESTED')}</span></div>${filtersMarkup()}<div class="countline"><span id="result-count" aria-live="polite"></span><button class="export-results" data-action="export-results">${icon('download')}${t('导出当前结果','Export these results')}</button></div><div class="card-grid ${state.view==='compact'?'compact':''}" id="card-grid"></div><div class="load-more" id="load-more"></div></section>${footer()}`;
 document.getElementById('status-filter').value=state.status;document.getElementById('sort-filter').value=state.sort;renderCards(favorites);}
function renderCards(fav=state.page==='favorites'){const result=searchStyles(index,{...state,lang:state.lang,favorites:fav?state.favorites:null});document.getElementById('result-count').textContent=t(`${result.length} 条结果 · 显示 ${Math.min(state.limit,result.length)} 条`,`${result.length} results · Showing ${Math.min(state.limit,result.length)}`);document.getElementById('card-grid').innerHTML=result.length?result.slice(0,state.limit).map(card).join(''):`<div class="empty-state"><h2>${(state.status==='images'||state.status==='examples')?t('案例图展厅暂时为空','The showcase gallery is still empty'):fav?t('你的收藏，从一种画风开始。','Your collection begins with a style.'):t('这里还没有匹配的风格。','No matching styles yet.')}</h2><p>${(state.status==='images'||state.status==='examples')?t('当前没有可显示的案例图。你也可以先浏览全部研究配方。','No showcase images are available for this filter yet. You can still browse all research recipes.'):fav?t('在风格卡上点按心形图标，即可保存在这台设备。','Tap the heart on any style card to keep it on this device.'):t('试试中文、英文或常见别名，也可以清除筛选。','Try a Chinese or English name or an alias, or clear the filters.')}</p><button class="button" data-action="reset-search">${t('浏览全部风格','Browse all styles')}${icon('arrow')}</button></div>`;
 document.getElementById('load-more').innerHTML=result.length>state.limit?`<button class="button" data-action="more">${t('再翻一页','Turn another page')} <span class="micro-note">${Math.min(24,result.length-state.limit)} / ${result.length-state.limit}</span>${icon('arrow')}</button>`:'';}
function sourceList(s){return s.sources.map(id=>sources.find(x=>x.id===id)).filter(Boolean).map(x=>`<a href="${e(safeHTTPS(x.url))}" target="_blank" rel="noopener noreferrer">${e(x.title)} ↗</a>`).join('');}
function modelTabs(which){const current=which==='work'?state.workModel:state.model;return `<div class="model-tabs" role="group" aria-label="${t('提示词版本','Prompt version')}">${MODELS.map(m=>`<button data-model="${m}" data-target="${which}" class="${current===m?'active':''}" aria-pressed="${current===m}">${{chatgpt:'ChatGPT',gemini:'Gemini',flux:'FLUX'}[m]}</button>`).join('')}</div>`;}
function promptLangControl(id,val){return `<select id="${id}" class="small-select" aria-label="${t('提示词语言','Prompt language')}"><option value="zh" ${val==='zh'?'selected':''}>${t('中文提示词','Chinese prompt')}</option><option value="en" ${val==='en'?'selected':''}>${t('英文提示词','English prompt')}</option></select>`;}
function renderDetail(){const s=byId.get(state.id);if(!s){renderNotFound();return;}const example=ex(s,state.model,state.promptLang),isMontage=example?.kind==='montage-derived-preview',isProcedural=example?.kind==='procedural-style-study',sameSceneOnly=example?.requestKind==='standalone-same-scene-generation',canSplit=example&&!isMontage&&!sameSceneOnly&&example.originalSha256===DATA.benchmark.sha256&&DATA.benchmark.path;const main=document.getElementById('main');const prompt=composePrompt(s,state.model,state.promptLang);main.innerHTML=`<div class="breadcrumb"><a href="${href('atlas')}" data-nav="atlas" data-restore="true">${t('风格图鉴','Atlas')}</a><span>/</span><button data-category="${s.category}">${e(catName(s.category))}</button><span>/</span><span>${e(familyName(s))}</span></div><section class="detail-grid"><div class="detail-visual">${canSplit?`<div class="split-view" id="split-view"><img src="${asset(DATA.benchmark.path)}" alt="${t('统一原图','Benchmark original')}"><img class="after-image" src="${asset(example.path)}" alt="${e(l(s.name))}"></div><label class="range-control">${isProcedural?t('原图 / 程序化预览','Original / procedural study'):t('原图 / 风格示意','Original / showcase')}<input id="split-range" type="range" min="0" max="100" value="50" aria-label="${t('原图与生成图分割线','Original-result divider')}"></label>`:`<div class="large-cover">${cover(s,true,state.model,state.promptLang)}</div>`}<p class="visual-note">${isMontage?t('这张临时风格图裁自生成拼图，使用不同于 B00 的人物。它不是独立的图生图生成结果，也未经当前提示词实测。','This provisional image is a crop from a generated style montage using a different portrait. It is not an independent B00 edit or a validation of the displayed prompt.'):isProcedural?t('本图由 B00 原图通过本地确定性绘图算法制作，不是 ImageGen 模型生成，也不代表当前提示词经过实测。','This is a deterministic rendering of B00 with local image-processing code, not an ImageGen model result or a validated preset prompt.'):sameSceneOnly?t('本图为独立生成的同场景风格示意，未证明 B00 原图被作为实际图像编辑输入，也未经本条提示词逐字复现。','This is a separately generated same-scene study. The exact B00 image-edit input and preset prompt were not verified.'):canSplit?t('本图为同一基准场景的风格示意；当前提示词没有逐字复现记录，不代表模型已通过验证。','This image illustrates a treatment of the benchmark scene. The current preset prompt has not been reproduced exactly and model validation is pending.'):t('这张图是用于目录识别的抽象封面，不是此提示词的生成结果。对应统一原图例图尚待制作。','This is an abstract index cover, not an output from this prompt. A same-input example is still pending.')}${example?.generationRecordStatus==='unavailable'?t(' 素材包未附生成编号。',' The source pack contains no generation ID.'):''}</p><div class="action-row"><button class="button favorite-btn" data-favorite="${s.id}" aria-pressed="${state.favorites.has(s.id)}">${icon('heart')}<span>${t('收藏风格','Save style')}</span></button><button class="button compare-btn" data-compare="${s.id}" aria-pressed="${state.compare.includes(s.id)}">${icon('compare')}${t('加入比较台','Add to comparison')}</button></div><div class="info-box"><h3>${t('具体视觉语言','Specific visual language')}</h3><p>${e(l(s.technique))}</p></div><div class="info-box warning"><h3>${t('需要避免的偏差','What should not drift')}</h3><p>${e(l(s.avoid))}</p></div><div class="info-box"><h3>${t('边界与限制','Limits')}</h3><p>${e(l(s.limits))}${s.preservation==='reinterpret'?'<br>'+t('此条目允许重构视角或构图，不属于严格保留镜头的纯转绘。','This entry permits viewpoint or composition changes; it is not a strict camera-preserving treatment.'):''}</p></div></div><div class="detail-copy"><div class="eyebrow">RECIPE ${String(s.order).padStart(3,'0')} / ${e(catName(s.category).toUpperCase())}</div><h1 class="detail-title">${e(l(s.name))}</h1><p class="detail-en">${e(state.lang==='zh'?s.name.en:s.name.zh)}</p><div class="detail-tags"><span class="small-tag">${e(familyName(s))}</span><span class="small-tag">${t('独立编写','Independently authored')}</span><span class="small-tag">v${e(s.version)}</span><span class="small-tag">${isMontage?t('拼图裁切参考 · 未实测','Montage crop · untested'):isProcedural?t('程序化视觉示意 · 非 AI 生图','Procedural artwork · not AI generated'):sameSceneOnly?t('同场景独立示意 · 未实测','Same-scene illustration · untested'):example?t('有风格示意图','Has a style illustration'):t('此版本待实测','This version is untested')}</span></div>${modelTabs('detail')}<div class="prompt-control-row">${promptLangControl('detail-lang',state.promptLang)}<span class="micro-note">${t('文本适配 ≠ 已验证兼容','Text adaptation ≠ tested compatibility')}</span></div><pre class="prompt-text" id="detail-prompt">${e(prompt)}</pre><div class="action-row"><button class="button primary" data-action="copy-detail">${icon('copy')}${t('复制完整提示词','Copy full prompt')}</button><button class="button" data-edit-style="${s.id}">${icon('edit')}${t('调整配方','Customize')}</button></div><p class="micro-note">${t('先复制提示词，再在自己的生图工具中重新上传原图。本站不传输图片或提供在线生图。','Copy the prompt, then upload your original in your own image tool. This site does not transfer images or generate online.')}</p><div class="action-row"><a class="button small" href="https://chatgpt.com/" target="_blank" rel="noopener noreferrer">${t('打开 ChatGPT','Open ChatGPT')}${icon('external')}</a><a class="button small" href="https://gemini.google.com/" target="_blank" rel="noopener noreferrer">${t('打开 Gemini','Open Gemini')}${icon('external')}</a><button class="button small" data-export-style="${s.id}">${icon('download')}${t('导出配方','Export recipe')}</button></div><div class="sources-box"><h3>${t('检索与技法参考','Discovery & technique references')}</h3><div class="source-links">${sourceList(s)}</div><p class="source-note">${t('上列页面是检索或技法参考，不代表原作者编写／验证过这条 Framegami 提示词。本站未复制第三方图片。','These are discovery or technique references, not claims that the original authors wrote or tested this Framegami recipe. No third-party images are copied.')}</p></div></div></section><section class="related"><h2>${t('沿着这条线，再看一看。','Follow the thread.')}</h2><div class="card-grid">${styles.filter(x=>x.category===s.category&&x.id!==s.id).slice(0,4).map(card).join('')}</div></section>${footer()}`;}
function renderTray(){const el=document.getElementById('compare-tray');el.hidden=!state.compare.length||state.page==='compare';if(el.hidden)return;el.innerHTML=`<span class="tray-label">${icon('compare')} ${t('比较台','Compare')} ${state.compare.length}/4</span><div class="tray-chips">${state.compare.map(id=>`<button class="tray-chip" data-compare="${id}" title="${e(l(byId.get(id).name))}" aria-label="${t('从比较台移除','Remove from comparison')} ${e(l(byId.get(id).name))}">${e(l(byId.get(id).name))} ×</button>`).join('')}</div><button class="button" data-action="open-compare" ${state.compare.length<2?'disabled':''}>${t('并排比较','Compare side by side')} →</button><button class="tray-clear" data-action="clear-compare">${t('清空','Clear')}</button>`;}
function renderCompare(){const selected=state.compare.map(id=>byId.get(id)).filter(Boolean),hasImages=selected.length>1&&selected.every(s=>ex(s,state.model,state.promptLang)),sameInput=hasImages&&selected.every(s=>{const image=ex(s,state.model,state.promptLang);return image?.kind!=='montage-derived-preview'&&image?.requestKind!=='standalone-same-scene-generation'&&image?.originalSha256===DATA.benchmark.sha256;}),hasProcedural=selected.some(s=>ex(s,state.model,state.promptLang)?.kind==='procedural-style-study');document.getElementById('main').innerHTML=`<section class="page-heading"><div class="eyebrow">SIDE BY SIDE / DIFFERENCE MATTERS</div><h1>${t('比较，而不只是收藏。','Compare, don’t just collect.')}</h1><p>${sameInput?(hasProcedural?t('这些图片均基于 B00 原图，但其中包含程序化图像处理预览，并非图像模型 Prompt 的生成结果。','All these studies use B00, but some are procedural image-processing previews, not image-model prompt results.'):t('同一原图，不同视觉语言。同步放大查看局部。','Same original, different visual languages. Zoom together to inspect detail.')):hasImages?t('图片来源可能不同；其中拼图裁切仅为临时风格示意，不可当作同原图模型实测对比。','These previews may use different sources. Montage crops are provisional visual references, not same-input generation benchmarks.'):t('当前可比较视觉规则、避错要求和完整提示词；有缺图条目时不展示虚假的效果对比。','Compare visual rules, constraints and prompts. No fake visual comparisons appear for missing images.')}</p></section>${selected.length<2?`<div class="empty-state"><h2>${t('先选两种风格','Choose at least two styles')}</h2><p>${t('最多比较四种。在风格卡上点按双栏图标即可添加。','Compare up to four styles. Tap the two-column icon on a style card.')}</p><a class="button" href="${href('atlas')}" data-nav="atlas">${t('返回图鉴','Back to atlas')}${icon('arrow')}</a></div>`:`<div class="compare-controls">${modelTabs('compare')}${promptLangControl('compare-lang',state.promptLang)}<button class="button small" data-action="clear-compare">${t('清空比较台','Clear comparison')}</button><button class="button small" data-action="share-compare">${icon('copy')}${t('复制比较链接','Copy comparison link')}</button><button class="button small" data-action="export-compare">${icon('download')}${t('导出比较配方','Export prompts')}</button>${sameInput?`<label class="range-control">${t('同步放大','Synced zoom')}<input id="compare-zoom" type="range" min="1" max="3" step="0.1" value="1"></label>`:''}</div><div class="compare-grid" style="--cols:${selected.length}">${selected.map(s=>`<article class="compare-column">${hasImages?`<div class="zoom-window"><img src="${asset(ex(s,state.model,state.promptLang).path)}" alt="${e(l(s.name))}"></div>`:`<div class="card-cover">${cover(s,false,state.model,state.promptLang)}</div>`}<h2>${e(l(s.name))}</h2><p>${e(familyName(s))} · ${ex(s,state.model,state.promptLang)?(ex(s,state.model,state.promptLang).kind==='montage-derived-preview'?t('拼图裁切示意','Montage crop preview'):ex(s,state.model,state.promptLang).kind==='procedural-style-study'?t('B00 程序化预览','B00 procedural study'):ex(s,state.model,state.promptLang).accepted?t('已验证例图','Validated example'):ex(s,state.model,state.promptLang).requestKind==='standalone-same-scene-generation'?t('同场景独立示意','Independent same-scene study'):t('同图案例图','Same-input showcase')):t('此版本待实测','This version is untested')}</p><h3>${t('视觉机制','Visual mechanism')}</h3><p>${e(l(s.technique))}</p><h3>${t('避免偏差','Avoid')}</h3><p>${e(l(s.avoid))}</p><h3>${t('完整提示词','Full prompt')}</h3><pre class="prompt-text">${e(composePrompt(s,state.model,state.promptLang))}</pre><div class="action-row"><button class="button small" data-copy-style="${s.id}">${icon('copy')}${t('复制','Copy')}</button><button class="button small" data-compare="${s.id}">${t('移除此项','Remove')}</button></div></article>`).join('')}</div>`}${footer()}`;renderTray();}
function workKey(){return [state.customEditing?'custom-draft-'+state.customEditing:state.workStyle,state.workModel,state.workLang].join(':');}
function saveWorkDraft(){writeLocal('draft:'+workKey(),{text:state.workText,dirty:state.workDirty,options:state.workOptions});}
function loadWorkDraft(){const saved=readLocal('draft:'+workKey(),null);if(saved&&typeof saved.text==='string'&&saved.text.length<=20000){state.workText=saved.text;state.workDirty=!!saved.dirty;state.workOptions=normalizePromptOptions(saved.options);}else if(state.customEditing){state.workDirty=true;}else{state.workOptions={background:'keep',palette:'style',detail:'balanced',extra:''};state.workText=composePrompt(byId.get(state.workStyle),state.workModel,state.workLang,state.workOptions);state.workDirty=false;}}
function fieldOptions(id,label,values,current){return `<div class="field"><label for="${id}">${label}</label><select id="${id}">${values.map(([v,zh,en])=>`<option value="${v}" ${current===v?'selected':''}>${t(zh,en)}</option>`).join('')}</select></div>`;}
function renderWorkbench(){if(!state.workText&&!state.customEditing)loadWorkDraft();const s=byId.get(state.workStyle);document.getElementById('main').innerHTML=`<section class="page-heading"><div class="eyebrow">THE PROMPT WORKBENCH</div><h1>${t('让配方，更像你的想法。','Make the recipe your own.')}</h1><p>${t('调整文字指令，或直接编辑完整 Prompt。选项不是模型 API 数值参数；这是一张不连接生图服务的工作台。','Adjust written directions or edit the full prompt. Controls compose text—not API parameters. This workbench does not connect to a generation service.')}</p></section><section class="workbench-grid"><div class="work-panel"><h2>${t('01 / 配方设置','01 / Recipe controls')}</h2><div class="field style-field"><label for="work-style">${t('基础风格','Base style')}</label><select id="work-style">${categories.map(c=>`<optgroup label="${e(c[state.lang])}">${styles.filter(s=>s.category===c.id).map(x=>`<option value="${x.id}" ${x.id===state.workStyle?'selected':''}>${e(l(x.name))}</option>`).join('')}</optgroup>`).join('')}</select></div>${fieldOptions('work-background',t('背景处理','Background'),[['keep','保留完整场景','Keep whole scene'],['simplify','保持位置，减少细节','Simplify in place'],['blank','移除背景，浅色留白','Remove background']],state.workOptions.background)}${fieldOptions('work-palette',t('配色指令','Palette direction'),[['style','遵从目标风格','Target style'],['source','优先原图色彩关系','Source relationships'],['mono','自定义单色变体','Monochrome variant']],state.workOptions.palette)}${fieldOptions('work-detail',t('细节指令','Detail direction'),[['balanced','主次平衡','Balanced'],['rich','保留次级细节','More secondary detail'],['simple','减少次要纹理','Simplified']],state.workOptions.detail)}<div class="field full-width"><label for="work-extra">${t('额外要求','Additional direction')}</label><textarea id="work-extra" maxlength="8000" placeholder="${t('例如：保留原图眼镜与服装标志性结构。','For example: retain the original glasses and distinctive clothing details.')}">${e(state.workOptions.extra)}</textarea></div><div class="full-width"><button class="button small" data-action="compose-work">${t('按设置重组提示词','Compose from controls')}${icon('arrow')}</button><p class="micro-note">${t('如果已手动编辑，会先确认，不静默覆盖。','Manual edits require confirmation before replacement.')}</p></div><div class="side-divider full-width"></div><div class="upload-wrap"><h2>${t('02 / 本地原图参考','02 / Local image reference')}</h2><label class="local-upload" for="local-image">${icon('upload')}<span>${t('选择自己的原图','Choose your original')}</span><small>JPG · PNG · WEBP · GIF / ≤ 15 MB</small></label><input type="file" id="local-image" accept="image/jpeg,image/png,image/webp,image/gif" class="sr-only">${localImageURL?`<img id="local-preview" class="local-preview" src="${e(localImageURL)}" alt="${t('仅本地显示的用户原图','Your locally displayed original')}"><button class="button small" data-action="remove-image">${t('移除图片','Remove image')}</button>`:'<div id="local-preview-slot"></div>'}<p class="upload-note">${t('仅在本设备预览，不上传、不写入仓库、不保存在收藏备份里。到目标工具仍需重新上传。','Previewed only on this device. Not uploaded, committed or included in backups. Upload it again in your chosen image tool.')}</p></div></div><div class="work-editor"><div class="prompt-control-row"><h2 style="font:600 13px var(--sans);margin:0">${state.customEditing?t('自定义配方编辑','Editing custom recipe'):t('03 / 完整提示词','03 / Full prompt')}</h2>${promptLangControl('work-lang',state.workLang)}</div>${modelTabs('work')}<textarea id="work-text" class="editor-area" placeholder="${t('在这里写下完整的图生图提示词。','Write your complete image-to-image prompt here.')}" maxlength="20000" spellcheck="false" aria-label="${t('可编辑的完整提示词','Editable full prompt')}">${e(state.workText)}</textarea><div class="editor-meta"><span id="work-dirty">${state.workDirty?t('已手动修改 · 只存本地','Manually edited · Local only'):t('按设置组成 · 未实测','Composed from controls · Untested')}</span><span id="work-length">${state.workText.length.toLocaleString()} ${t('字符','characters')}</span></div><div class="action-row"><button class="button primary" data-action="copy-work">${icon('copy')}${t('复制完整提示词','Copy full prompt')}</button>${state.customEditing&&state.custom.some(x=>x.id===state.customEditing)?`<button class="button" data-action="update-custom">${icon('check')}${t('保存当前配方','Save changes')}</button>`:''}<button class="button" data-action="save-custom">${icon('heart')}${t('另存自定义配方','Save custom recipe')}</button><button class="button" data-action="export-work">${icon('download')}${t('导出 Markdown','Export Markdown')}</button></div><div class="info-box warning"><h3>${t('你控制的是文字，不是模型参数。','You are editing text, not model parameters.')}</h3><p>${t('这些选项会改变实际复制的提示词。没有隐藏的“强度 73%”，也不会在后台调用你的账号。ChatGPT 是主验证目标，当前这条配方仍未实测。','These controls change the prompt that gets copied. There is no hidden “73% strength” and no account is called in the background. ChatGPT is the primary validation target; this recipe is still untested.')}</p></div><div class="action-row"><a class="button small" href="https://chatgpt.com/" target="_blank" rel="noopener noreferrer">${t('打开 ChatGPT','Open ChatGPT')}${icon('external')}</a><a class="button small" href="https://gemini.google.com/" target="_blank" rel="noopener noreferrer">${t('打开 Gemini','Open Gemini')}${icon('external')}</a><button class="button small" data-action="reset-work">${t('恢复该风格默认配方','Restore default recipe')}</button></div></div></section>${footer()}`;}
function renderCustom(){document.getElementById('main').innerHTML=`<section class="page-heading"><div class="eyebrow">PERSONAL RECIPES / LOCAL FIRST</div><h1>${t('你的风格，自己命名。','Your style. Your name.')}</h1><p>${t('自定义内容只保存在当前浏览器。导入采用合并；编号冲突会保留两份，不覆盖已有文字。','Custom content stays in this browser. Imports merge; conflicting IDs keep both versions rather than overwriting text.')}</p><div class="action-row"><button class="button primary" data-action="new-custom">${icon('plus')}${t('新建空白配方','New blank recipe')}</button><button class="button" data-action="export">${icon('download')}${t('导出备份','Export backup')}</button><button class="button" data-action="import">${icon('upload')}${t('导入备份','Import backup')}</button></div></section><div class="custom-list">${state.custom.length?state.custom.map(x=>`<article class="custom-card"><div class="source-meta">${e(x.model.toUpperCase())} / ${e(x.lang.toUpperCase())} / ${t('仅本地','LOCAL ONLY')}</div><h2>${e(x.name)}</h2><div class="custom-tags">${normalizeTags(x.tags).map(tag=>`<span>${e(tag)}</span>`).join('')}</div><p>${e(x.prompt.slice(0,240))}${x.prompt.length>240?'…':''}</p><div class="action-row"><button class="button small" data-copy-custom="${e(x.id)}">${icon('copy')}${t('复制','Copy')}</button><button class="button small" data-edit-custom="${e(x.id)}">${icon('edit')}${t('编辑','Edit')}</button><button class="button small" data-delete-custom="${e(x.id)}">${t('删除','Delete')}</button></div></article>`).join(''):`<div class="empty-state"><h2>${t('留给下一次灵感。','A place for your next idea.')}</h2><p>${t('从任意风格进入工作台调整并保存，或者直接新建一份空白提示词。','Customize a style in the workbench and save it, or start with a blank prompt.')}</p></div>`}</div>${footer()}`;}
function renderAbout(){const familyCount=categories.reduce((n,c)=>n+Object.keys(c.families).filter(f=>styles.some(s=>s.category===c.id&&s.family===f)).length,0);document.getElementById('main').innerHTML=`<section class="page-heading"><div class="eyebrow">AN OPEN NOTEBOOK, NOT A MAGIC FILTER</div><h1>${t('把来源、方法和边界，都摊开。','Show the sources. Show the limits.')}</h1><p>${t('Framegami 是公开分享的图生图提示词研究工具。我们区分风格配方、对应例图和重复验证，不把它们混成一个漂亮数字。','Framegami is an openly shareable image-to-image prompt research tool. Authored recipes, corresponding examples and repeated validation are different things.')}</p></section><div class="about-stats"><div class="about-stat"><strong>${styles.length}</strong><span>${t('独立配方草案','Independent recipe drafts')}</span></div><div class="about-stat"><strong>${categories.length} / ${familyCount}</strong><span>${t('门类 / 风格家族','Categories / families')}</span></div><div class="about-stat"><strong>${styles.filter(s=>ex(s)).length}</strong><span>${t('有案例图的风格','Styles with showcase images')}</span></div><div class="about-stat"><strong>${sources.length}</strong><span>${t('记录在案的参考来源','Recorded references')}</span></div></div><div class="about-grid"><section class="about-block"><h2>${t('01 · 什么已经有了','01 · What is here')}</h2><p>${t('中英双语目录、多级分类、别名搜索、配方比较、多模型文字版本、编辑、收藏、自定义、导入导出。所有条目的状态都由数据决定。','A bilingual catalog, nested categories, alias search, recipe comparison, model-specific text versions, editing, collections, custom recipes and backup import/export. Entry status is data-driven.')}</p><p>${t('每条文本是针对本项目独立编写的风格迁移配方。来源用于发现候选、理解技法或校验模型使用方式，不是复制来的上游测试证明。','Each prompt is independently authored for this project. References support discovery, technique or model guidance; they are not borrowed evidence that a Framegami recipe passed.')}</p></section><section class="about-block"><h2>${t('02 · 什么还没有完成','02 · What remains incomplete')}</h2><p>${t('已保存 B00 原图与独立生成的同场景展示图。另有单独标注的其他人物拼图裁切，以及通过 B00 确定性图像处理代码制作的视觉预览；这两类都不算模型生成的独立样本。逐条 Prompt 验证尚未完成。','The B00 original and independently generated same-scene showcases remain available. Additional montage crops of a different portrait and deterministic B00 processing studies are distinctly labeled and never counted as independent model generations. Exact-prompt tests remain incomplete.')}</p><p>${t('不声称“全网最全”“所有模型兼容”或“任何图片必定成功”。抽象风格、精细五官、透视与材质之间仍有需要测试的取舍。','There is no claim of exhaustive web coverage, universal model compatibility or guaranteed success. Abstraction, facial detail, perspective and material treatment still require trade-off testing.')}</p></section><section class="about-block"><h2>${t('03 · 例图进入正式馆的条件','03 · Example admission rules')}</h2><p>${t('使用同一个冻结原图；每种风格独立从原图生成。记录原图哈希、完整 Prompt 哈希、版本、真实使用环境、输出文件哈希和日期。','Use one frozen original and generate each style independently from it. Record original hash, full prompt hash, version, actual generation environment, output hash and date.')}</p><p>${t('检查身份、构图、目标画风、全画面一致性与结构问题。当前站内案例图可以作为风格浏览的 showcase；只有同时具备图片、完整 Prompt 证据和审查记录时，条目才会升级为正式验证例图。提示词更新后，旧例图不会自动获得新版本验证资格。','Identity, composition, target style, whole-scene coherence and structural issues must still be reviewed. Current in-site images may serve as showcase browsing assets; a style becomes a formally validated example only when image evidence, exact prompt evidence and review records are all present. A prompt revision does not automatically validate the new version.')}</p></section><section class="about-block"><h2>${t('04 · 隐私和本地数据','04 · Privacy & local data')}</h2><p>${t('本站不提供 API Key 输入框，不调用生图服务，不设置登录，不使用分析追踪。个人图片只建立本地预览 URL，移除后释放；收藏与自定义配方保存在当前浏览器。','No API-key form, generation calls, login or analytics. Personal images receive only local preview URLs, revoked on removal. Collections and custom prompts remain in this browser.')}</p><p>${t('导出文件含收藏编号和自定义文字，不包含你的原图。清除浏览器数据会丢失本地收藏，请自行保留导出备份。第三方工具有自己的隐私政策。','Backup files include saved IDs and custom text, not your original images. Clearing browser storage removes local content; keep an export. External tools have their own privacy policies.')}</p></section><section class="about-block" id="deployment"><h2>GitHub</h2><p><a href="https://github.com/patshin/framegami">${t('查看源码与使用说明','Source code and usage guide')} ↗</a></p></section><section class="about-block"><h2>${t('06 · 如何贡献','06 · How to contribute')}</h2><p>${t('优先补充已存在风格的真实例图与失败记录，而不是新增一个近义词。新风格必须解释线条、色彩、材质或空间组织上的实际区别。','Prioritize real examples and failure reports for existing styles over adding synonyms. New styles must explain concrete differences in line, color, material or spatial organization.')}</p><p>${t('代码采用 MIT；独立配方文本采用 CC0。第三方来源页面与作品不在授权范围内，也没有打包第三方字体。文化艺术方向是视觉研究，不冒充传统技艺认证。','Code is MIT-licensed; independently authored recipe text is CC0. Third-party pages and artwork are not relicensed, and no third-party font files are bundled. Cultural treatments are visual studies, not certified traditional craft.')}</p></section></div><section style="margin-top:32px"><h2 class="section-title">${t('参考来源台账','Reference ledger')}</h2><p class="large-source-note">${t('检索日期：2026-10-17。下面逐项区分模型官方指南、社区案例、技法说明和部署资料。网页可访问性可能变化；这份台账不代表逐一实测了所有上游内容。','Research date: 2026-10-17. Entries distinguish official model guidance, community examples, technique references and deployment documentation. Availability can change; this is not a claim that all upstream content was tested.')}</p><div class="source-directory">${sources.map(x=>`<article class="source-entry"><span class="source-meta">${e(x.kind)} / ${e(x.language.toUpperCase())}</span><h3>${e(x.title)}</h3><p>${e(l(x.note))}</p><a href="${e(safeHTTPS(x.url))}" target="_blank" rel="noopener noreferrer">${t('打开原始来源','Open original source')} ↗</a></article>`).join('')}</div></section>${footer()}`;}
function renderNotFound(){document.getElementById('main').innerHTML=`<div class="empty-state" style="margin-top:40px"><h1>${t('这一页尚未收录。','This page is not in the atlas.')}</h1><p>${t('链接可能无效，或者该条目还在整理。','The link may be invalid or the entry may still be in preparation.')}</p><a class="button" href="${href('atlas')}" data-nav="atlas">${t('返回图鉴','Back to atlas')}</a></div>${footer()}`;}
function renderPage(){document.title=(state.page==='style'&&byId.has(state.id)?l(byId.get(state.id).name)+' — ':'')+t('Framegami｜图生图风格图鉴','Framegami · Image-to-image Style Atlas');switch(state.page){case'atlas':renderAtlas();break;case'favorites':renderAtlas(true);break;case'style':renderDetail();break;case'compare':renderCompare();break;case'workbench':renderWorkbench();break;case'custom':renderCustom();break;case'about':renderAbout();break;default:renderNotFound();}renderTray();}
function updateToggles(){document.querySelectorAll('[data-favorite]').forEach(el=>el.setAttribute('aria-pressed',state.favorites.has(el.dataset.favorite)));document.querySelectorAll('[data-compare]').forEach(el=>{if(el.matches('.compare-btn'))el.setAttribute('aria-pressed',state.compare.includes(el.dataset.compare));});document.querySelectorAll('[data-fav-count]').forEach(el=>el.textContent=state.favorites.size);document.querySelectorAll('[data-custom-count]').forEach(el=>el.textContent=state.custom.length);renderTray();}
function download(name,content,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportBackup(){download('iro-backup.json',JSON.stringify({schema:'iro-backup/v1',version:VERSION,exportedAt:new Date().toISOString(),favorites:[...state.favorites],custom:state.custom},null,2));toast(t('备份已导出，不含个人原图。','Backup exported without personal images.'));}
function showDialog(title,body,buttons=[]){const d=document.getElementById('action-dialog');d.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${e(title)}</h2><button data-close aria-label="${t('关闭','Close')}">${icon('close')}</button></div>${body}<div class="action-row">${buttons.map(b=>`<button class="button ${b.primary?'primary':''}" data-dialog-action="${b.action}">${e(b.label)}</button>`).join('')}</div>`;d.setAttribute('aria-labelledby','dialog-title');d.showModal();return d;}
async function copyText(text){try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(text);toast(t('提示词已复制。请在生图工具重新上传原图。','Prompt copied. Upload your original in your image tool.'));return;}}catch{}const area=document.createElement('textarea');area.value=text;area.style.cssText='position:fixed;left:-10000px';document.body.append(area);area.select();let ok=false;try{ok=document.execCommand('copy');}catch{}area.remove();if(ok)toast(t('提示词已复制。','Prompt copied.'));else{const d=showDialog(t('手动复制提示词','Copy the prompt manually'),`<p class="dialog-copy">${t('浏览器限制了剪贴板。下方内容已选中，按 Ctrl/Cmd+C 复制。','The browser restricted clipboard access. Press Ctrl/Cmd+C to copy the selected text.')}</p><textarea id="manual-copy" class="dialog-textarea" readonly>${e(text)}</textarea>`);d.querySelector('textarea').select();}}
function requestCompose(reset=false){const apply=()=>{if(reset)state.workOptions={background:'keep',palette:'style',detail:'balanced',extra:''};state.workText=composePrompt(byId.get(state.workStyle),state.workModel,state.workLang,state.workOptions);state.workDirty=false;state.customEditing=null;saveWorkDraft();renderWorkbench();};if(state.workDirty){showDialog(t('替换手动编辑的内容？','Replace your manual edits?'),`<p class="dialog-copy">${t('重组会替换当前编辑区。先另存自定义配方可保留这份文字。','Recomposing replaces the editor text. Save a custom recipe first to keep these edits.')}</p>`,[{action:reset?'confirm-reset':'confirm-compose',label:t('替换当前内容','Replace text'),primary:true},{action:'cancel',label:t('保留编辑','Keep edits')}]);}else apply();}
function refreshWorkTextFromControls(){if(state.workDirty){document.getElementById('work-dirty').textContent=t('设置已变更：重组前会确认，不覆盖手动文字。','Controls changed: recomposing will confirm before replacing edits.');saveWorkDraft();return;}state.workText=composePrompt(byId.get(state.workStyle),state.workModel,state.workLang,state.workOptions);const area=document.getElementById('work-text');if(area)area.value=state.workText;const length=document.getElementById('work-length');if(length)length.textContent=state.workText.length.toLocaleString()+' '+t('字符','characters');saveWorkDraft();}
function promptFor(s){return composePrompt(s,state.model,state.promptLang);}
document.addEventListener('click',ev=>{const target=ev.target instanceof Element?ev.target.closest('a,button'):null;if(!target)return;
 if(target.tagName==='A'&&(ev.metaKey||ev.ctrlKey||ev.shiftKey||ev.altKey||ev.button!==0))return;
 if(target.hasAttribute('data-close')){target.closest('dialog')?.close();return;}
 if(target.dataset.nav){ev.preventDefault();document.getElementById('mobile-menu').close();if(target.dataset.clear){state.category='';state.family='';state.tag='';state.q='';state.status='all';state.treatment='all';state.limit=24;}navigate(target.dataset.nav,target.dataset.id||'',{restore:target.dataset.restore==='true'});return;}
 if(target.hasAttribute('data-category')){state.category=target.dataset.category;state.family='';state.limit=24;document.getElementById('mobile-menu').close();if(state.page!=='atlas')navigate('atlas');else{syncURL(true);renderShell();renderAtlas();}document.getElementById('explore')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});return;}
 if(target.hasAttribute('data-family')){state.category=target.dataset.parent;state.family=target.dataset.family;state.limit=24;document.getElementById('mobile-menu').close();if(state.page!=='atlas')navigate('atlas');else{syncURL(true);renderShell();renderAtlas();}document.getElementById('explore')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});return;}
 if(target.dataset.favorite){const id=target.dataset.favorite;if(!known.has(id))return;if(state.favorites.has(id))state.favorites.delete(id);else state.favorites.add(id);persist();updateToggles();if(state.page==='favorites')renderCards(true);toast(state.favorites.has(id)?t('已收藏到当前浏览器。','Saved on this browser.'):t('已从收藏移除。','Removed from collection.'));return;}
 if(target.dataset.compare){const id=target.dataset.compare;if(!known.has(id))return;if(state.compare.includes(id))state.compare=state.compare.filter(x=>x!==id);else if(state.compare.length<4)state.compare.push(id);else{toast(t('最多比较四种风格，请先移除一种。','Compare up to four styles. Remove one first.'));return;}persist();updateToggles();if(state.page==='compare'){syncURL(true);renderCompare();}return;}
 if(target.hasAttribute('data-treatment')){state.treatment=target.dataset.treatment;state.limit=24;syncURL(true);renderAtlas(state.page==='favorites');return;}
 if(target.hasAttribute('data-tag')){state.tag=target.dataset.tag;state.limit=24;syncURL(true);renderAtlas(state.page==='favorites');return;}
 if(target.dataset.view){state.view=target.dataset.view;writeLocal('view',state.view);renderAtlas(state.page==='favorites');return;}
 if(target.dataset.model){if(target.dataset.target==='work'){saveWorkDraft();state.workModel=target.dataset.model;loadWorkDraft();renderWorkbench();}else{state.model=target.dataset.model;if(state.page==='compare')syncURL(true);state.page==='compare'?renderCompare():renderDetail();}return;}
 if(target.dataset.editStyle){saveWorkDraft();state.workStyle=target.dataset.editStyle;state.workModel=state.model;state.workLang=state.promptLang;state.customEditing=null;loadWorkDraft();navigate('workbench');return;}
 if(target.dataset.copyStyle){copyText(promptFor(byId.get(target.dataset.copyStyle)));return;}
 if(target.dataset.exportStyle){const s=byId.get(target.dataset.exportStyle);download('iro-'+s.id+'.json',JSON.stringify({schema:'iro-recipe/v1',id:s.id,name:s.name,model:state.model,lang:state.promptLang,prompt:promptFor(s),validation:getAcceptedExample(s,state.model,state.promptLang)?'single-example':'untested',promptVersion:s.version,tags:s.tags,sources:s.sources.map(id=>sources.find(x=>x.id===id)?.url).filter(Boolean)},null,2));return;}
 if(target.dataset.copyCustom){const x=state.custom.find(x=>x.id===target.dataset.copyCustom);if(x)copyText(x.prompt);return;}
 if(target.dataset.editCustom){const x=state.custom.find(x=>x.id===target.dataset.editCustom);if(x){state.workText=x.prompt;state.workModel=x.model;state.workLang=x.lang;state.workDirty=true;state.customEditing=x.id;loadWorkDraft();navigate('workbench');}return;}
 if(target.dataset.deleteCustom){const id=target.dataset.deleteCustom;const x=state.custom.find(x=>x.id===id);if(x)showDialog(t('删除这份自定义配方？','Delete this custom recipe?'),`<p class="dialog-copy">${e(x.name)}<br>${t('仅删除当前浏览器中的这份内容，已导出的备份不会受影响。','Only this browser copy will be removed. Exported backups are not affected.')}</p>`,[{action:'delete:'+id,label:t('确认删除','Delete'),primary:true},{action:'cancel',label:t('取消','Cancel')}]);return;}
 if(target.dataset.dialogAction){const action=target.dataset.dialogAction,d=document.getElementById('action-dialog');if(action==='cancel'){d.close();return;}if(action==='update-custom'){const pos=state.custom.findIndex(x=>x.id===state.customEditing);if(pos<0||!state.workText.trim()){toast(t('提示词不能为空。','The prompt cannot be empty.'));return;}state.custom[pos]={...state.custom[pos],prompt:state.workText,model:state.workModel,lang:state.workLang,updatedAt:new Date().toISOString()};persist();saveWorkDraft();toast(t('当前配方已保存；其他配方没有被修改。','Recipe saved. Other recipes were not changed.'));return;}
 if(action==='save-custom'){const name=d.querySelector('#custom-name').value.trim();if(!name){d.querySelector('#custom-name').focus();return;}if(!state.workText.trim()){toast(t('提示词不能为空。','The prompt cannot be empty.'));return;}if(state.custom.length>=MAX_CUSTOM){toast(t('自定义条目已达上限，请先导出备份。','Custom recipe limit reached. Export a backup first.'));return;}const id='custom-'+(globalThis.crypto?.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2,8));state.custom.push({id,name:name.slice(0,120),prompt:state.workText,model:state.workModel,lang:state.workLang,tags:normalizeTags(d.querySelector('#custom-tags')?.value||''),createdAt:new Date().toISOString()});persist();d.close();updateToggles();toast(t('自定义配方已保存到当前浏览器。','Custom recipe saved in this browser.'));return;}if(action==='confirm-compose'||action==='confirm-reset'){d.close();state.workDirty=false;requestCompose(action==='confirm-reset');return;}if(action.startsWith('delete:')){state.custom=state.custom.filter(x=>x.id!==action.slice(7));persist();d.close();renderShell();renderCustom();return;}if(action==='confirm-import'&&importPayload){try{const merged=mergeBackup({favorites:[...state.favorites],custom:state.custom},importPayload);state.favorites=new Set(merged.favorites);state.custom=merged.custom;persist();importPayload=null;d.close();renderShell();renderPage();toast(t('备份已合并，没有覆盖冲突的配方。','Backup merged. Conflicting recipes were not overwritten.'));}catch(err){toast(err.message);}return;}}
 const action=target.dataset.action;if(!action)return;
 if(action==='language'){state.lang=state.lang==='zh'?'en':'zh';syncURL();renderShell();renderPage();writeLocal('lang',state.lang);return;}
 if(action==='menu'){document.getElementById('mobile-menu').showModal();return;}
 if(action==='explore'){ev.preventDefault();document.getElementById('explore')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});return;}
 if(action==='more'){state.limit+=24;renderCards();return;}
 if(action==='clear-filters'){state.category='';state.family='';state.limit=24;syncURL(true);renderShell();renderAtlas(state.page==='favorites');return;}
 if(action==='reset-search'){state.q='';state.category='';state.family='';state.tag='';state.status='all';state.treatment='all';state.limit=24;if(state.page==='favorites')navigate('atlas');else{syncURL(true);renderShell();renderAtlas();}return;}
 if(action==='open-compare'){navigate('compare');return;}
 if(action==='clear-compare'){state.compare=[];persist();updateToggles();if(state.page==='compare'){syncURL(true);renderCompare();}return;}
 if(action==='copy-detail'){copyText(promptFor(byId.get(state.id)));return;}
 if(action==='copy-work'){copyText(state.workText);return;}
 if(action==='compose-work'){requestCompose();return;}
 if(action==='reset-work'){requestCompose(true);return;}
 if(action==='update-custom'){const pos=state.custom.findIndex(x=>x.id===state.customEditing);if(pos<0||!state.workText.trim()){toast(t('提示词不能为空。','The prompt cannot be empty.'));return;}state.custom[pos]={...state.custom[pos],prompt:state.workText,model:state.workModel,lang:state.workLang,updatedAt:new Date().toISOString()};persist();saveWorkDraft();toast(t('当前配方已保存；其他配方没有被修改。','Recipe saved. Other recipes were not changed.'));return;}
 if(action==='save-custom'){showDialog(t('给这份配方一个名字','Name your recipe'),`<label class="dialog-copy" for="custom-name">${t('只保存在当前浏览器，可以随时导出备份。','Saved only in this browser. You can export a backup at any time.')}</label><input class="dialog-input" id="custom-name" maxlength="120" value="${e(state.customEditing?state.custom.find(x=>x.id===state.customEditing)?.name||'':l(byId.get(state.workStyle).name))}" placeholder="${t('我的配方名称','My recipe name')}"><label class="dialog-copy tag-field" for="custom-tags">${t('标签（逗号分隔，最多12个）','Tags (comma separated, up to 12)')}</label><input class="dialog-input" id="custom-tags" maxlength="480" placeholder="${t('例如：人像、柔和、我的收藏','e.g. portraits, soft, favorites')}">`,[{action:'save-custom',label:t('保存为新配方','Save as new recipe'),primary:true},{action:'cancel',label:t('取消','Cancel')}]);return;}
 if(action==='export-work'){download('iro-custom-prompt.md',`# Framegami custom prompt\n\nModel target: ${state.workModel}\nLanguage: ${state.workLang}\nStatus: user-edited / untested\n\n${state.workText}\n`,'text/markdown;charset=utf-8');return;}
 if(action==='new-custom'){state.workText='';state.workDirty=true;state.customEditing='new';state.workOptions=normalizePromptOptions();navigate('workbench');return;}
 if(action==='remove-image'){if(localImageURL)URL.revokeObjectURL(localImageURL);localImageURL='';renderWorkbench();return;}
 if(action==='export-results'){const entries=filteredEntries();if(!entries.length){toast(t('当前没有可导出的结果。','No results to export.'));return;}download('iro-selection-'+entries.length+'.md',exportPromptCollection(entries,state.model,state.promptLang),'text/markdown;charset=utf-8');toast(t(`已导出 ${entries.length} 条配方；未测试的版本仍标为待测。`,`Exported ${entries.length} recipes with their validation status.`));return;}
 if(action==='export-compare'){download('iro-comparison.md',exportPromptCollection(state.compare.map(id=>byId.get(id)),state.model,state.promptLang),'text/markdown;charset=utf-8');return;}
 if(action==='share-compare'){if(location.protocol==='file:'||CONFIG.preview){toast(t('单文件预览不生成公共链接，请使用导出比较配方。','Standalone preview has no public URL. Export the comparison instead.'));return;}copyText(href('compare'));return;}
 if(action==='export'){exportBackup();return;}
 if(action==='import'){document.getElementById('import-file').click();return;}
});
document.addEventListener('input',ev=>{const el=ev.target;if(el.id==='style-search'){clearTimeout(searchTimer);state.q=el.value;state.limit=24;searchTimer=setTimeout(()=>{syncURL(true);renderCards();},100);}if(el.id==='work-text'){state.workText=el.value;state.workDirty=true;document.getElementById('work-length').textContent=state.workText.length.toLocaleString()+' '+t('字符','characters');document.getElementById('work-dirty').textContent=t('已手动修改 · 只存本地','Manually edited · Local only');saveWorkDraft();}if(el.id==='work-extra'){state.workOptions.extra=el.value;refreshWorkTextFromControls();}if(el.id==='split-range'){document.getElementById('split-view').style.setProperty('--split',el.value+'%');}if(el.id==='compare-zoom'){document.querySelectorAll('.zoom-window').forEach(x=>x.style.setProperty('--zoom',el.value));}});
document.addEventListener('change',async ev=>{const el=ev.target;if(el.id==='status-filter'||el.id==='sort-filter'){state[el.id==='status-filter'?'status':'sort']=el.value;state.limit=24;syncURL(true);renderCards();return;}if(el.id==='detail-lang'||el.id==='compare-lang'){state.promptLang=el.value;if(state.page==='compare')syncURL(true);state.page==='compare'?renderCompare():renderDetail();return;}if(el.id==='work-style'||el.id==='work-lang'){saveWorkDraft();if(el.id==='work-style'){state.workStyle=el.value;state.customEditing=null;}else state.workLang=el.value;loadWorkDraft();renderWorkbench();return;}if(['work-background','work-palette','work-detail'].includes(el.id)){state.workOptions[el.id.slice(5)]=el.value;refreshWorkTextFromControls();return;}if(el.id==='local-image'){const f=el.files?.[0];if(!f)return;if(f.size>15*1024*1024||!['image/jpeg','image/png','image/webp','image/gif'].includes(f.type)){toast(t('请使用 15 MB 内的 JPG、PNG、WebP 或 GIF。','Use a JPG, PNG, WebP or GIF under 15 MB.'));el.value='';return;}const url=URL.createObjectURL(f);try{await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>img.naturalWidth*img.naturalHeight>50e6?reject(new Error('Image too large')):resolve();img.onerror=reject;img.src=url;});if(localImageURL)URL.revokeObjectURL(localImageURL);localImageURL=url;renderWorkbench();toast(t('图片仅在本设备预览。','Image preview stays on this device.'));}catch{URL.revokeObjectURL(url);toast(t('无法读取图片，或像素尺寸过大。','Unreadable image or excessive pixel dimensions.'));}return;}if(el.id==='import-file'){const f=el.files?.[0];el.value='';if(!f)return;if(f.size>MAX_IMPORT_BYTES){toast(t('备份文件不能超过 2 MB。','Backup files must be under 2 MB.'));return;}try{importPayload=validateImport(JSON.parse(await f.text()),known);showDialog(t('合并这份备份？','Merge this backup?'),`<p class="dialog-copy">${t('只接收合法的收藏编号与自定义提示词字段，不执行文件里的 HTML 或脚本。','Only valid saved IDs and custom-prompt fields are accepted. No HTML or scripts in the file are executed.')}</p><div class="import-summary">${importPayload.favorites.length} ${t('个收藏','saved styles')} · ${importPayload.custom.length} ${t('份自定义配方','custom recipes')}</div>`,[{action:'confirm-import',label:t('合并并保留已有内容','Merge and keep existing content'),primary:true},{action:'cancel',label:t('取消','Cancel')}]);}catch(err){importPayload=null;toast(t('导入失败：','Import failed: ')+err.message);}return;}});
document.addEventListener('pointermove',ev=>{if(state.page!=='compare')return;const w=ev.target instanceof Element?ev.target.closest('.zoom-window'):null;if(!w)return;const r=w.getBoundingClientRect();const x=(ev.clientX-r.left)/r.width*100,y=(ev.clientY-r.top)/r.height*100;document.querySelectorAll('.zoom-window').forEach(n=>{n.style.setProperty('--zx',x+'%');n.style.setProperty('--zy',y+'%');});});
document.addEventListener('keydown',ev=>{const tag=document.activeElement?.tagName;const typing=['INPUT','TEXTAREA','SELECT'].includes(tag)||document.activeElement?.isContentEditable;if(ev.key==='/'&&!typing&&!document.querySelector('dialog[open]')){ev.preventDefault();if(!['atlas','favorites'].includes(state.page))navigate('atlas');document.getElementById('style-search')?.focus();}if(ev.key==='Escape'&&state.page==='atlas'&&!typing&&state.q){state.q='';renderAtlas();syncURL(true);}});
window.addEventListener('popstate',()=>{parseRoute();restoreViewQuery();renderShell();renderPage();window.scrollTo({top:state.page==='atlas'?scrollMemory:0,behavior:'instant'});});
window.addEventListener('pagehide',()=>{if(localImageURL)URL.revokeObjectURL(localImageURL);});
window.addEventListener('storage',ev=>{if(!ev.key?.startsWith(STORAGE+':'))return;if(ev.key.endsWith(':favorites')){const raw=readLocal('favorites',[]);state.favorites=new Set(Array.isArray(raw)?raw.filter(x=>known.has(x)):[]);updateToggles();if(state.page==='favorites')renderCards(true);}});
renderShell();renderPage();if(storageWarning)toast(t('本地存储受限，请保留导出备份。','Local storage is restricted. Keep an exported backup.'));
})();
